@custom-variant dark (&:is(.dark *));

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-brand: var(--brand);
  --color-brand-foreground: var(--brand-foreground);
  --color-accent2: var(--accent2);

  --font-sans:
    "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-display:
    "Space Grotesk", "Inter", ui-sans-serif, system-ui, sans-serif;
}

:root {
  --radius: 0.875rem;

  /* Light — warm off-white with sun-on-coast accents */
  --background: oklch(0.985 0.005 230);
  --foreground: oklch(0.18 0.03 250);

  --card: oklch(1 0 0 / 0.6);
  --card-foreground: oklch(0.18 0.03 250);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.18 0.03 250);

  --primary: oklch(0.22 0.04 250);
  --primary-foreground: oklch(0.98 0.005 230);
  --secondary: oklch(0.95 0.015 240);
  --secondary-foreground: oklch(0.22 0.04 250);
  --muted: oklch(0.95 0.01 240);
  --muted-foreground: oklch(0.45 0.025 250);
  --accent: oklch(0.94 0.03 220);
  --accent-foreground: oklch(0.22 0.04 250);

  --destructive: oklch(0.58 0.22 27);
  --destructive-foreground: oklch(0.98 0.005 230);

  --border: oklch(0.85 0.015 240 / 0.6);
  --input: oklch(0.9 0.015 240);
  --ring: oklch(0.65 0.15 220);

  /* Brand: ocean teal -> coral, Aussie coastal feel */
  --brand: oklch(0.68 0.16 215);
  --brand-foreground: oklch(0.99 0.005 230);
  --accent2: oklch(0.72 0.18 35);

  --gradient-brand: linear-gradient(
    135deg,
    oklch(0.72 0.16 215) 0%,
    oklch(0.68 0.18 280) 50%,
    oklch(0.74 0.18 35) 100%
  );
  --gradient-aurora: radial-gradient(
      60% 50% at 15% 10%,
      oklch(0.78 0.18 215 / 0.35),
      transparent 70%
    ),
    radial-gradient(
      50% 40% at 90% 0%,
      oklch(0.75 0.2 320 / 0.3),
      transparent 70%
    ),
    radial-gradient(
      45% 50% at 50% 100%,
      oklch(0.78 0.18 35 / 0.25),
      transparent 70%
    );

  --shadow-glass:
    0 1px 0 0 oklch(1 0 0 / 0.6) inset,
    0 10px 30px -12px oklch(0.2 0.05 250 / 0.18);
  --glass-bg: oklch(1 0 0 / 0.55);
  --glass-border: oklch(1 0 0 / 0.6);
}

[data-theme="dark"] {
  --background: oklch(0.16 0.025 260);
  --foreground: oklch(0.97 0.005 230);

  --card: oklch(0.22 0.03 260 / 0.55);
  --card-foreground: oklch(0.97 0.005 230);
  --popover: oklch(0.2 0.03 260);
  --popover-foreground: oklch(0.97 0.005 230);

  --primary: oklch(0.97 0.005 230);
  --primary-foreground: oklch(0.18 0.03 260);
  --secondary: oklch(0.27 0.03 260);
  --secondary-foreground: oklch(0.97 0.005 230);
  --muted: oklch(0.26 0.03 260);
  --muted-foreground: oklch(0.72 0.02 250);
  --accent: oklch(0.3 0.04 250);
  --accent-foreground: oklch(0.97 0.005 230);

  --destructive: oklch(0.7 0.19 22);
  --destructive-foreground: oklch(0.98 0.005 230);

  --border: oklch(1 0 0 / 0.1);
  --input: oklch(1 0 0 / 0.14);
  --ring: oklch(0.7 0.14 215);

  --brand: oklch(0.78 0.16 215);
  --brand-foreground: oklch(0.15 0.03 260);
  --accent2: oklch(0.78 0.18 35);

  --gradient-aurora: radial-gradient(
      60% 50% at 15% 10%,
      oklch(0.6 0.2 215 / 0.4),
      transparent 70%
    ),
    radial-gradient(
      50% 40% at 90% 0%,
      oklch(0.55 0.22 300 / 0.4),
      transparent 70%
    ),
    radial-gradient(
      45% 50% at 50% 100%,
      oklch(0.65 0.2 35 / 0.3),
      transparent 70%
    );

  --shadow-glass:
    0 1px 0 0 oklch(1 0 0 / 0.08) inset,
    0 12px 40px -12px oklch(0 0 0 / 0.5);
  --glass-bg: oklch(0.26 0.03 260 / 0.55);
  --glass-border: oklch(1 0 0 / 0.14);
}

@layer base {
  * {
    border-color: var(--color-border);
  }
  html {
    color-scheme: light dark;
  }
  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }
  h1, h2, h3, h4 {
    font-family: var(--font-display);
    letter-spacing: -0.015em;
  }
}

/* Glassmorphism utilities */
@utility glass {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  backdrop-filter: blur(18px) saturate(160%);
  box-shadow: var(--shadow-glass);
}

@utility glass-strong {
  background: color-mix(in oklab, var(--glass-bg) 70%, var(--background));
  border: 1px solid var(--glass-border);
  backdrop-filter: blur(24px) saturate(180%);
  box-shadow: var(--shadow-glass);
}

@utility text-gradient-brand {
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

@utility bg-aurora {
  background: var(--gradient-aurora);
}

/* --------------------------------------------------------------- */
/* Motion utilities — pure CSS, opt-in per element                  */
/* --------------------------------------------------------------- */

@keyframes anim-fade-up {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes anim-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes anim-scale-in {
  from { opacity: 0; transform: scale(0.97); }
  to   { opacity: 1; transform: scale(1); }
}
@keyframes anim-float {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-6px); }
}
@keyframes anim-gradient-shift {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
@keyframes anim-shimmer {
  from { background-position: -200% 0; }
  to   { background-position: 200% 0; }
}

@utility anim-fade-up {
  animation: anim-fade-up 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@utility anim-fade-in {
  animation: anim-fade-in 0.5s ease-out both;
}
@utility anim-scale-in {
  animation: anim-scale-in 0.45s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@utility anim-float {
  animation: anim-float 6s ease-in-out infinite;
}
@utility anim-gradient-shift {
  background-size: 200% 200%;
  animation: anim-gradient-shift 12s ease-in-out infinite;
}

/* Staggered children — apply to a parent, its direct children fade up
   in sequence. Keeps everything in CSS, no IntersectionObserver. */
.anim-stagger > * {
  animation: anim-fade-up 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.anim-stagger > *:nth-child(1) { animation-delay: 0.04s; }
.anim-stagger > *:nth-child(2) { animation-delay: 0.10s; }
.anim-stagger > *:nth-child(3) { animation-delay: 0.16s; }
.anim-stagger > *:nth-child(4) { animation-delay: 0.22s; }
.anim-stagger > *:nth-child(5) { animation-delay: 0.28s; }
.anim-stagger > *:nth-child(6) { animation-delay: 0.34s; }
.anim-stagger > *:nth-child(7) { animation-delay: 0.40s; }
.anim-stagger > *:nth-child(8) { animation-delay: 0.46s; }
.anim-stagger > *:nth-child(n + 9) { animation-delay: 0.5s; }

/* Hover primitives */
@utility hover-lift {
  transition:
    transform 0.25s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.25s ease;
}
.hover-lift:hover {
  transform: translateY(-2px);
}

@utility link-underline {
  background-image: linear-gradient(hsl(var(--brand)), hsl(var(--brand)));
  background-repeat: no-repeat;
  background-size: 0% 2px;
  background-position: 0 100%;
  transition: background-size 0.3s ease;
}
.link-underline:hover {
  background-size: 100% 2px;
}

/* Global niceties */
html {
  scroll-behavior: smooth;
}
a,
button {
  transition:
    color 0.2s ease,
    background-color 0.2s ease,
    border-color 0.2s ease,
    opacity 0.2s ease;
}
:focus-visible {
  outline: 2px solid hsl(var(--brand));
  outline-offset: 2px;
  border-radius: 8px;
}

/* Respect user motion preferences */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}
